import Foundation

/// One version in What's new.
public struct Release: Sendable, Equatable {
    public let version: String
    public let date: String
    public let items: [String]
}

/// The words of Settings: What's new (every version, newest first) and How it works.
public enum AppText {
    public static let releases: [Release] = [
        Release(version: "1.6", date: "3 November 2026", items: [
            "New: exercises without a machine. The gym's add tile now says \"New machine or exercise\". Push-ups, sit-ups and pull-ups can be logged in the gym log like any machine, with reps only and no weight.",
            "New: \"Skip photo\". When the camera opens for a new machine, a \"Skip photo\" button goes straight to the form without a photo. The tile then shows the hand-drawn strength mark instead of a picture.",
            "New: \"What you log\" in the machine form has a third choice, \"Reps only\", next to Weight × reps and Time. The form is then headed \"New exercise\" (\"Edit exercise\" when you change one), and the delete button says \"Delete exercise\".",
            "New: a reps-only exercise has its own \"Rest\" setting (none up to 5:00 in 15-second steps, usual 1:30) but no weight step and no \"More weight at\", because there is no weight.",
            "New: a new reps-only exercise starts at 10 reps. On the exercise screen you only set the reps, with − and + (or type the number). The set editor and \"Next time\" ask for reps only too.",
            "New: getting stronger on an exercise. When every set last time reached the first set's reps, it suggests one rep more — for example \"Try 16 reps — every set last time reached 15\".",
            "New: \"New best\" on a reps-only exercise means the most reps in one set. The small chart in History shows reps per visit, and its axis says reps.",
            "New: reps-only exercises are written plainly. A set reads \"12 reps\", an entry \"15, 15, 12 reps\", and the tile on the gym screen shows \"Last: 15 reps\".",
            "New: Plan today, Busy, Next ›, notes, \"Next time\" and the history of earlier visits all work for exercises just as they do for machines.",
            "New: a plank. Choose Time in \"What you log\" and turn \"Has a level\" and \"Has an incline\" off — you log only the minutes.",
            "Changed: a visit with only reps-only exercises no longer shows \"0 kg\". The \"Lifted\" tile and month line in History, the visit page and the Finish summary leave the kilograms out, and \"Lifted in all\" is hidden when nothing was lifted.",
            "New: Settings → Backups. A new row in Settings opens a page for keeping your data safe.",
            "New: \"Back up now\" (a full-colour navy button) makes ONE file, named like \"Workouts backup 2026-11-03 1530.json\", with all your workouts, the gym log, History and every photo. The iPhone's share sheet opens so you can save it to Files, iCloud Drive or send it by AirDrop. A file in iCloud Drive stays safe even if the app is deleted.",
            "New: \"Restore from a file…\" lets you pick a backup file. The app reads it first: a file that is not a Workouts backup, or is damaged, is refused and nothing is changed. Otherwise it shows the date of the backup and what it holds — for example \"3 workouts · 12 machines · 40 gym visits · 25 other sessions · 30 photos\" — and asks before going on.",
            "New: Restore replaces what is on the iPhone with the backup. Before it does, today's data is kept aside in a \"Before restore\" folder inside the app, so a wrong restore can be undone.",
            "New: \"On this iPhone\". Once a week, when the app starts, it keeps a copy of everything by itself. The newest 4 are kept and older ones go. They are listed with their date; tap one to restore it (the same question is asked first). \"Keep a copy now\" makes one at once. These copies go if the app is deleted, so keep one in Files too.",
            "Changed: machines and everything you logged before 1.6 are untouched. Your older data reads exactly as before.",
            "Fixed: each gym keeps its own plan for today. Before, the app kept one plan for all gyms, so planning a second gym wiped the first gym's plan.",
            "New: choose your own icons. On a workout's edit page, tap Icon. Touch and hold the At the gym tile and tap \"Change icon…\". A machine or exercise without a photo has an Icon row in its form. Every picker has a search, Cancel, Save and \"Use the usual icon\".",
            "Changed: \"At the gym\" on the Train tab is one size larger.",
        ]),
        Release(version: "1.5", date: "3 November 2026", items: [
            "New: three tabs at the bottom of the app, each with a hand-drawn mark — Train, History and Settings. Train keeps its place when you switch between tabs; History and Settings open fresh.",
            "New: the Train tab is headed \"Workout Companion\". The name under the app icon stays \"Workouts\".",
            "New: on Train, At the gym is a wide indigo tile at the top, in full colour. Your workouts are full-colour tiles in two columns, each with its icon, name, a summary and a play mark. Tap a tile to start it, tap the pencil at its top right to edit it, or touch and hold it for Edit, Duplicate and Delete.",
            "New: a dashed \"New workout\" tile after your workouts. The + at the top right still makes a new workout too.",
            "New: \"Log an earlier day…\" in the gym-name menu, for a session you forgot to log. It opens a calendar (Cancel and Done). While an earlier day is chosen, an orange bar says \"Logging for Saturday 31 October\" with \"Back to today\".",
            "New: \"On this machine\" in the machine form (weight machines only) — three settings for each machine. \"Rest after each set\": none up to 5:00 in 15-second steps (usual 1:30). \"Weight step\": 1, 2.5 or 5 kg (usual 2.5). \"More weight at\": 3 to 50 reps (usual 12).",
            "New: the weight step is used by − and + on the machine and in \"Next time\", and by the suggestion of more weight.",
            "New: when every set last time reached the \"More weight at\" number of reps, the machine suggests one step more next time, with two reps fewer — for example \"Try 45 kg — every set last time reached 10 reps\".",
            "New: with the rest set to none, Set done goes straight on to the next set, with no rest ring.",
            "Changed: History is no longer a card among your workouts. It has its own tab.",
            "Changed: Settings is a tab too, so it has no Done button, and the gear at the top left of the home screen is gone.",
            "Changed: the date at the top right of the gym screen is gone. It is always today by itself; use \"Log an earlier day…\" for another day.",
            "Changed: machines you do not change keep the usual 1:30 rest, 2.5 kg step and 12 reps, so everything works as before.",
            "New: on the gym machine screen, from the first set on, a green \"Next ›\" button sits on the same line as \"Set done\" (\"Done\" on a time machine), with the next planned machine's name in small letters under \"Next\". It takes the place of the separate \"Done with this machine\" button under the sets, and does the same job: to the next planned machine, else back to the machines.",
            "New: time machines (treadmill, rowing machine, bike) can say what they have. In the machine's edit page, \"On this machine\" has two switches, \"Has a level\" and \"Has an incline\" (both on as usual). Turn off the level on a treadmill, or the incline on a bike: the machine screen and \"Next time\" then only ask for what the machine has, and the words leave it out — \"25 min · incline 3 %\".",
            "Changed: History is more colourful. The four \"This week\" numbers are full-colour tiles — Sessions plum, Minutes green, Lifted indigo, Weeks in a row orange — and each filter chip has its own colour: All plum, At the gym indigo, and each workout its own colour.",
            "Fixed: tapping a session in History opens it again. In 1.4 it showed an empty page with a yellow warning triangle.",
            "Changed: History and Settings open fresh each time you choose their tab. Train keeps its place, so the gym screen stays where you were.",
        ]),
        Release(version: "1.4", date: "3 November 2026", items: [
            "New: more than one gym. The gym's name sits at the top of the gym screen — tap it to switch gym, to make a \"New gym…\" or to \"Rename this gym…\". Each gym has its own machines and its own visits. Everything you had before is now in \"My gym\" (you can rename it). The app opens at the gym you used last.",
            "New: Plan today (you do not have to use it). Tap \"Plan today\", tap the machines in the order you want them, then Save. \"Today's plan\" lists them with numbers and shows Up next, Done, Busy or Skipped.",
            "New: touch and hold a planned machine for Later (to the end of the plan), Skip today (and Back in today's plan), Swap for… or Remove from plan. You can still tap any machine whenever you like. A busy machine is passed over, and Finish ends the plan.",
            "New: \"Done with this machine\" under the sets, from the first set on. With a plan it goes straight to the next planned machine (\"Next: Leg press\"); without one it takes you back to the machines.",
            "New: during the rest, once you have done as many sets as last time, a big \"Next machine\" button appears (with the machine's name when there is a plan).",
            "New: machines for time — treadmill, rowing machine, bike. In the machine form, \"What you log\" is Weight × reps or Time. Time logs minutes, level and incline (%), shown like \"25 min · level 8 · incline 2.5 %\". A new time machine starts at 20 min, level 5. There is no rest ring and no New best for time.",
            "New: \"How did it feel? Next time…\" after the first set. Choose next time's weight and reps (or time, level and incline) and write a note. Next time the machine starts with those numbers (\"Your plan from last time: 45 kg × 15\") and shows your note under \"Last time\". Earlier visits show them too.",
            "New: Instructions photo. In the machine form, \"Instructions\" lets you take or choose a photo of the machine's instruction plate. On the machine screen a small \"Instructions\" picture opens it full screen.",
            "New: after Finish (\"Session done\") you can give the visit a title (suggested: \"Tuesday at My gym\") and write notes. They are saved with Done. Earlier visits show the title, and the pencil on a visit changes its title and notes (Cancel and Save).",
            "New: History — a new plum card under At the gym on the home screen. It lists every gym session and every Sets & reps, Interval and Exercise-list workout you did, newest first, finished or ended early (marked \"ended early\").",
            "New: History has filter chips — All, At the gym, and one for each workout. At the top: this week (sessions, minutes, kilograms lifted, weeks in a row), a line for this month, and a bar chart of minutes per week for the last 8 weeks.",
            "New: tap a workout in History to see its details; the pencil changes its title and notes, and \"Delete from History\" removes it after asking. Tap a gym session to open the visit.",
            "Changed: \"Skip\" during a rest now says \"Skip rest\" — at the gym and in Sets & reps and Interval workouts.",
            "Changed: \"Finish\" at the gym now says \"Finish this session\".",
            "Fixed: correcting or removing a set you had already done, and saving a plan, could close the app. They no longer do.",
        ]),
        Release(version: "1.3", date: "3 November 2026", items: [
            "New: Busy. When someone is on a machine, tap Busy on its photo. The machine turns orange and moves up to a new row, \"Come back to\", at the top of the gym screen — so you remember it once you have done the others.",
            "New: when the machine is free, just tap it. Opening it, or doing a set on it, takes the Busy mark away by itself. A second tap on Busy also takes it away.",
            "New: Finish clears every Busy mark of the day, and a mark left from another day never comes back.",
            "Changed: the machines that are not busy are listed under \"Other machines\" while something is busy; otherwise the gym screen looks as before.",
        ]),
        Release(version: "1.2", date: "3 November 2026", items: [
            "New: At the gym — the card at the top of Workouts. For a gym where you use machines in whatever order they come free.",
            "New: at a new machine, the camera opens; then you give it a name and, if you like, how it is set up (\"Seat 4, handles 2\"). The date is today by itself; the date at the top changes it.",
            "New: each machine is a photo tile. Tap whichever is free. A tick shows the machines done today; the line under it says how many sets, or the weight last time.",
            "New: on a machine you see its photo (tap to enlarge), its setting, and what you did last time. Weight and reps are filled in from last time, so a set is usually one tap on Set done. − and + change the weight by 2.5 kg and the reps by 1; tap a number to type it. 0 kg means body weight.",
            "New: Set done starts a 1:30 rest with a ring, +15 s and Skip, and a beep and spoken words when the next set starts. Tap a set you did to change or remove it.",
            "New: when every set last time reached 12 reps, the machine suggests 2.5 kg more. A weight heavier than ever before shows New best.",
            "New: every machine keeps its history, with a small chart of your heaviest weight per visit.",
            "New: Finish shows what the visit came to — machines, sets, time, kilograms lifted in all, and the new bests. Earlier visits are listed under the machines.",
            "Changed: Save is now a full-colour button. With no name yet it stays blue and says \"Give it a name first\" instead of being greyed out.",
            "Fixed: two buttons had no name for the app's tests (Cancel on New workout, End workout); now they do.",
        ]),
        Release(version: "1.1", date: "2 November 2026", items: [
            "New: Settings, from the gear at the top left of Workouts — with How it works, What's new and the version number.",
            "New: every icon is hand-drawn, from the shared AMS icon library — a kettlebell for Sets & reps, a stretching figure for Exercise lists, a stopwatch for Interval timers.",
            "New: the marks on the buttons (Done, Skip, Pause, Close, Add, Edit…) are hand-drawn too, from the same shared library.",
            "New: the app icon is a white hand-drawn stopwatch on a calm orange background.",
            "Changed: the colours are the fifteen shared AMS colours, in two rows of eight. A workout that had Light blue or Light yellow now shows orange until you pick again.",
            "Changed: Workouts, New workout and the exercise list are more compact — smaller tiles, less space between rows, standard text sizes.",
            "Changed: a new workout has Cancel as well as Save.",
            "Changed: the name under the app icon is now Workouts. It was Companion, which Apple keeps for one of its own apps.",
        ]),
        Release(version: "1.0", date: "2 November 2026", items: [
            "The first version: Sets & reps with a rest timer, Exercise lists with a note and a photo per exercise, and Interval timers.",
            "Sound, vibration and spoken words during a workout; the screen stays on.",
            "Three examples to start with: Push-ups, Intervals and Doctor's exercises.",
        ]),
    ]

    public static let howItWorks: [(title: String, text: String)] = [
        ("Workouts", "The app has three tabs at the bottom: Train, History and Settings; each keeps its place when you switch. Train is headed \"Workout Companion\" (the name under the app icon is \"Workouts\"). At the top is the wide indigo At the gym tile. Below it, your workouts are full-colour tiles in two columns. Tap a tile to start it. The pencil at its top right changes it. Touch and hold a tile for Edit, Duplicate or Delete. The dashed \"New workout\" tile and the + at the top right make a new one."),
        ("Sets & reps", "For one exercise in sets, like push-ups 5 × 20. During the workout you see the set and the reps in large numbers. Tap Done after each set; the rest timer starts by itself. +15 s gives more rest, Skip rest ends the rest early. A finished or ended workout goes into History."),
        ("Exercise lists", "For a list of different exercises, like the ones from your doctor. Each exercise has a name, an amount (\"3 × 10\"), a note on how to do it and, if you like, a photo. During the workout, tap an exercise to tick it off; tap the photo to see it large. When every exercise is ticked, the list says Well done."),
        ("Interval timers", "Rounds of work and rest against the clock, after a 5-second Get ready. Pause stops the clock, Skip rest goes straight to the next part. A finished or ended workout goes into History."),
        ("Sounds and words", "At the start of every set, round and rest the iPhone beeps, vibrates and says what comes next. The last three seconds of a countdown tick. The screen stays on while a workout runs, and the sound plays even with the ring/silent switch on."),
        ("At the gym", "The card at the top of Workouts. The gym's name is at the top of the gym screen: tap it to switch gym, make a \"New gym…\" or \"Rename this gym…\". Each gym has its own machines and visits; the app opens at the gym you used last. At each machine: tap \"New machine or exercise\", take a photo (or tap Skip photo if there is nothing to photograph, like push-ups), give it a name and, if you like, how it is set up — \"Seat 4, handles 2\". Next time, tap the machine's photo; use the machines in any order, whichever is free. The day is always today by itself. Forgot to log a session? Tap the gym's name, then \"Log an earlier day…\", pick the day in the calendar and tap Done. An orange bar says \"Logging for Saturday 31 October\"; \"Back to today\" returns."),
        ("Plan today", "If you like to know what comes next: tap Plan today, tap the machines in the order you want, then Save. Today's plan shows numbers and Up next, Done, Busy or Skipped. Touch and hold a planned machine for Later, Skip today (and Back in today's plan), Swap for… or Remove from plan. You can still tap any machine you like, busy machines are passed over, and Finish ends the plan."),
        ("Next ›", "From the first set on, a green \"Next ›\" button sits on the same line as Set done (\"Done\" on a time machine), with the next planned machine's name in small letters under it. It takes you straight to that machine; without a plan, or at the end of it, back to the machines. During the rest, once you have done as many sets as last time, a big \"Next machine\" button does the same."),
        ("Busy machines", "Someone on a machine? Tap Busy on its photo. It turns orange and moves to \"Come back to\" at the top, so you do the other machines first and do not forget it. When it is free, tap the machine — the Busy mark goes by itself. Tap Busy again to take the mark away without opening it. Finish clears every Busy mark."),
        ("Logging a set", "On a machine you see what you did last time, and the weight and reps are already filled in from it. Change what is different with − and + (the machine's weight step, usually 2.5 kg, and 1 rep) or tap the number to type it; 0 kg means body weight. Set done saves the set and starts the rest — usually 1:30, +15 s for more, Skip rest to go on. If the machine's rest is set to none, Set done goes straight on to the next set. Tap a set you did to change or remove it."),
        ("Machines for time", "For a treadmill, rowing machine or bike, choose Time under \"What you log\" in the machine form. You log minutes, level and incline (%) — \"25 min · level 8 · incline 2.5 %\". A new time machine starts at 20 min, level 5. There is no rest ring and no New best for time. In the machine's edit page, \"On this machine\" has the switches \"Has a level\" and \"Has an incline\" (both on as usual): turn one off, say the level on a treadmill or the incline on a bike, and the machine screen and \"Next time\" only ask for what the machine has — \"25 min · incline 3 %\"."),
        ("Exercises without a machine", "Push-ups, sit-ups or pull-ups: tap \"New machine or exercise\", then \"Skip photo\" if you have nothing to photograph (the tile shows the hand-drawn mark). Under \"What you log\" choose \"Reps only\". The form is headed \"New exercise\" and has its own Rest setting, but no weight step. A new exercise starts at 10 reps; you only set the reps. Sets read \"12 reps\", an entry \"15, 15, 12 reps\", and the tile says \"Last: 15 reps\". Plan, Busy, Next ›, notes and Next time work as for machines. A plank: choose Time and turn \"Has a level\" and \"Has an incline\" off. A visit with only exercises like these shows no \"0 kg\"."),
        ("Next time and notes", "After the first set, \"How did it feel? Next time…\" lets you choose next time's weight and reps (or time, level and incline) and write a note. Next time the machine starts with those numbers (\"Your plan from last time: 45 kg × 15\") and shows your note under \"Last time\". Earlier visits show them too."),
        ("Instructions photo", "In the machine form, \"Instructions\" takes or chooses a photo of the machine's instruction plate. On the machine screen a small \"Instructions\" picture opens it full screen."),
        ("Getting stronger", "On an exercise without weight (see Exercises without a machine), when every set last time reached the first set's reps, it suggests one rep more — \"Try 16 reps — every set last time reached 15\" — and New best means the most reps in one set. On a weight machine, when every set last time reached the machine's \"More weight at\" reps (usually 12), the machine suggests one weight step more (usually 2.5 kg) with two reps fewer — \"Try 45 kg — every set last time reached 10 reps\". A weight heavier than you ever did on that machine shows New best. Each machine shows its history and a small chart of your heaviest weight per visit (reps per visit for an exercise). Finish this session shows the whole visit: machines, sets, time, kilograms lifted and the new bests. Then you can give the visit a title (like \"Tuesday at My gym\") and notes, saved with Done; the pencil on an earlier visit changes them. The pencil on a machine changes its photo, name, setting or what it logs, or deletes it with all its sets."),
        ("History", "The History tab. Every gym session and every Sets & reps, Interval and Exercise-list workout, newest first — finished or \"ended early\". Chips filter: All (plum), At the gym (indigo), or one workout in its own colour. At the top: this week as four full-colour tiles — Sessions plum, Minutes green, Lifted indigo, Weeks in a row orange, a line for this month and a bar chart of minutes per week for the last 8 weeks. Tap a workout for its details; the pencil changes its title and notes, and \"Delete from History\" removes it after asking. Tap a gym session to open the visit. History and Settings open fresh each time you choose their tab; Train keeps its place."),
        ("On this machine", "In the machine form, for weight machines, \"On this machine\" has three settings. Rest after each set: none up to 5:00 in 15-second steps (usual 1:30). Weight step: 1, 2.5 or 5 kg (usual 2.5); − and + on the machine and in \"Next time\" use it. More weight at: 3 to 50 reps (usual 12). Machines you do not change keep the usual numbers."),
        ("Backups", "Settings → Backups. \"Back up now\" makes one file (\"Workouts backup 2026-11-03 1530.json\") with your workouts, gym log, History and every photo, and opens the share sheet: save it to Files or iCloud Drive, or AirDrop it. \"Restore from a file…\" lets you pick a backup. The app reads it first — a file that is not a backup, or is damaged, is refused and nothing changes — then shows its date and what it holds (\"3 workouts · 12 machines · 40 gym visits · 25 other sessions · 30 photos\") and asks. Restore replaces what is on the iPhone, after keeping today's data aside in a \"Before restore\" folder in the app. Under \"On this iPhone\", once a week when the app starts it keeps a copy by itself (the newest 4 stay). Tap one to restore it, or tap \"Keep a copy now\". These copies go if the app is deleted, so also keep one in Files."),
        ("Icons", "Every workout, the At the gym tile and each machine or exercise without a photo can have its own hand-drawn icon. Workout: edit page → Icon. At the gym: touch and hold the tile → \"Change icon…\". Machine or exercise: its form → Icon (only while it has no photo). Search by word, tap an icon, then Save; \"Use the usual icon\" goes back."),
        ("Making a workout", "Give it a name, pick a colour and choose its type. The numbers change with − and +. For an exercise list, Add exercise adds one; its ••• menu moves it up or down or removes it. Add photo takes a picture from your Photos. Nothing is kept until you tap Save; Cancel leaves everything as it was. Save needs a name — without one it tells you so."),
        ("Where things are kept", "Everything stays on this iPhone unless you save a backup file somewhere. The gym log keeps every visit in every gym, and History keeps your workouts, so you can see last time and your progress. Apple Health is not connected."),
    ]
}
